class Context:
    """
    A context indicating the intermediate state of a builder when going down
    the instruction tree. Keep track of indentation level, local variables,
    and variable environments. And maybe more (hence the class)
    """

    def __init__(
        self,
        /,
        *,
        parent: Instruction | None = None,
        level=0,
        environment: InstructionEnvironment | None = None,
        namespace: Namespace | None = None,
        assignments: dict | None = None,
        name: str | None = None,
        _names: List[str] | None = None,
    ):
        if environment is None:
            environment = InstructionEnvironment()

        if namespace is None:
            namespace = Namespace()

        if assignments is None:
            assignments = {}

        if parent is None:
            self._parent = None
        else:
            self._parent = ref(parent)

        self._container = None
        self._level = level
        self._namespace = namespace
        self._environment = environment
        self._assignments = assignments
        self._names = []

        if name is not None:
            self._names.append(name)

    # there is only one assignments instance being passed down a routine.

    @property
    def name(self):
        """return a readable name from name combinations"""
        if self._names:
            return "_".join(self._names)
        else:
            return "_"

    def hashed_name(self, num_symbols=8):
        """return a shortened hashed name"""
        return sha256(self.name).hexdigest()[:num_symbols]

    @property
    def parent(self):
        """access read-only attribute parent"""
        if self._parent is None:
            return None
        # weakref
        return self._parent()

    @property
    def level(self):
        """access read-only attribute level"""
        return self._level

    @property
    def environment(self):
        """access read-only attribute environment"""
        return self._environment

    @property
    def namespace(self):
        """access read-only attribute namespace"""
        return self._namespace

    @property
    def assignments(self):
        """access assignments"""
        return self._assignments

    @property
    def container(self):
        """access container"""
        return self._container

    def set_container(self, container):
        """set container"""
        if self._container is not None:
            raise ValueError("Cannot change container once set")
        self._container = container
        return self

    def new_namespace_node(self):
        """provide a new namespace node"""
        if self._namespace is None:
            self._namespace = Namespace()
        else:
            self._namespace = self._namespace.inherit()

    def set_assignment(self, instruction_variable_class, assignment):
        """set the assignment for an instruction variable class"""
        self._assignments[instruction_variable_class] = assignment

    def inherit(
        self,
        name=None,
        parent=None,
        environment=None,
        namespace=None,
    ):
        """
        Inherit to a new context object.
        Increment the level, optionally extend the namespace.
        Default behaviour for previous namespace and environment
        """

        if name is not None:
            self._names.append(name)

        if parent is None:
            if self.container is None:
                parent = self.parent
            else:
                parent = self.container

        if environment is None:
            environment = self.environment

        if namespace is None:
            if self.namespace is None:
                namespace = Namespace()
            else:
                namespace = (
                    self.namespace
                )  # .inherit()  use new_namespace_node

        return Context(
            parent=parent,
            level=self.level + 1,
            namespace=namespace,
            environment=environment,
            assignments=self.assignments,
            _names=self._names,
        )


class BuilderSegment:
    """Anything that handles instructions in the context of the build process"""

    _CLSNAME_PREFIX = "_SEGMENT_"
    _IDENTIFIER = "_GENERIC_"
    _VERSN = 0
    _BUILD = 0

    def _welcome_log(self):
        info(*self._welcome_log_lines())

    def _welcome_log_lines(self):
        version, build = type(self)._VERSN, type(self)._BUILD
        yield (
            f"Hello from {type(self)._CLSNAME_PREFIX} "
            + f"'{type(self)._IDENTIFIER}'"
            + f" (v{version}.{build})"
        )
        yield from self._detail_log_lines()

    def _detail_log_lines(self):
        yield f"parameters ({len(self._params)}):"
        for param, value in self._params.items():
            yield f"  - {param}={value}"

    @property
    def identifier(self):
        """access the identifier"""
        return type(self)._IDENTIFIER

    @classmethod
    def __init_subclass__(
        cls,
        identifier=None,
        version=None,
        build=None,
    ):
        if identifier is None:
            identifier = cls.__name__.upper()
        cls._IDENTIFIER = identifier
        if version is not None:
            cls._VERSN = version
        if build is not None:
            cls._BUILD = build


class Optimizer(BuilderSegment):
    """Optimize the instruction tree w.r.t. certain aspects"""

    def __init__(self, _internal=None, **params):
        self._params: Dict[str, Any] = params
        if _internal is None:
            _internal = {}
        _log_welcome = _internal.get("_log_welcome", True)
        if _log_welcome:
            self._welcome_log()

    def __str__(self):
        param_string = "|".join(
            [f"{key}={val}" for key, val in self._params.items()]
        )
        return f"<{self._CLSNAME_PREFIX}.{self.identifier}: {param_string}>"

    def __repr__(self):
        # param_string = "|".join(
        #     [f"{key}={val}" for key, val in self._params.items()]
        # )
        return f"<{self._CLSNAME_PREFIX}.{self.identifier}>"

    @log.wrap_call
    def apply(self, instruction_tree):
        """apply the optimizer"""
        raise NotImplementedError(
            "apply method must be implemented in subclass"
        )


